// @name Home Assistant remote
// @background #0f172a
// @refresh 60
// A touch remote for Home Assistant. The cards come from the scene's Cards
// setting, one entity per line ("# Name" lines start a page). Each render asks
// Home Assistant for the state of the cards on the page showing, one
// GET /api/states/<entity_id> each (never the whole /api/states list, which
// can be megabytes), and a tap calls a service
// (POST /api/services/<domain>/<service>). The card changes at once, and
// Home Assistant's answer (the states the call changed) puts it right.
//
// The address and the access token are the FrameOS account's Home Assistant
// settings (frameos.getSetting). Without them the scene draws what to set up.
import {
  Button, Card, Confirm, Header, Icon, SetupScreen, Slider, Switch, Tabs, Value,
  ago, capitalize, clamp, clockTime, columnsFor, iconName, niceNumber, parseCards, roundRoom, sizesOf, themeOf, words,
} from './ui'
import type { Entry, Look, Page, Sizes, Theme } from './ui'

// A state fetched less than this long ago is not asked for again (a tap
// renders at once, and so do a few taps in a row).
const FRESH_MS = 5000
// After a tap the card shows what it asked for this long, unless Home
// Assistant answers sooner, before a fetch may say otherwise.
const HOLD_MS = 4000

// ---------------------------------------------------------------- talking to Home Assistant

type Server = { url: string; token: string }

function serverOf(): Server | null {
  const url = String(frameos.getSetting('homeAssistant', 'url') || '').trim().replace(/\/+$/, '')
  const token = String(frameos.getSetting('homeAssistant', 'accessToken') || '').trim()
  return url && token ? { url, token } : null
}

// scheme://host:port of the address, for messages: never a path.
const originOf = (url: string) => (/^[a-z]+:\/\/[^/]+/i.exec(url) || [url])[0]

type Reply = { status: number; data?: any; error?: string }

function call(server: Server, method: string, path: string, body?: any): Reply {
  const reply = frameos.httpRequest(server.url + path, {
    method,
    headers: {
      Authorization: `Bearer ${server.token}`,
      Accept: 'application/json',
      'Content-Type': 'application/json',
    },
    body: body === undefined ? undefined : JSON.stringify(body),
    timeoutMs: 8000,
  })
  if (!reply.status) return { status: 0, error: reply.error || 'no answer' }
  if (reply.status >= 400) return { status: reply.status, error: (reply.body || '').slice(0, 120) }
  try {
    return { status: reply.status, data: reply.body ? JSON.parse(reply.body) : null }
  } catch (e) {
    return { status: reply.status, error: 'Home Assistant sent something that is not JSON' }
  }
}

// What a failed request means to a person.
function problemText(server: Server, reply: Reply) {
  if (reply.status === 401 || reply.status === 403)
    return 'Home Assistant refused the access token: check the access token in the Home Assistant settings.'
  const error = reply.error || `HTTP ${reply.status}`
  if (error.startsWith('Local network access is off'))
    return `${error}. Turn on Local network access in the frame's settings to reach ${originOf(server.url)}.`
  if (!reply.status) return `Could not reach Home Assistant at ${originOf(server.url)}: ${error}`
  return `Home Assistant answered ${error}`
}

// ---------------------------------------------------------------- states, kept small

// The attributes any card draws; the rest of an entity's state is dropped as
// soon as it arrives.
const ATTRS = [
  'friendly_name', 'unit_of_measurement', 'device_class', 'icon', 'supported_features',
  'brightness', 'supported_color_modes', 'color_temp_kelvin', 'min_color_temp_kelvin', 'max_color_temp_kelvin',
  'percentage', 'current_temperature', 'temperature', 'target_temp_low', 'target_temp_high', 'target_temp_step',
  'min_temp', 'max_temp', 'hvac_modes', 'hvac_action', 'current_humidity', 'current_position',
  'media_title', 'media_artist', 'app_name', 'volume_level', 'battery_level', 'last_triggered',
  'humidity', 'temperature_unit', 'min', 'max', 'step',
]
type Slim = { state: string; changed: number; a: Record<string, any> }

function slim(entity: any): Slim {
  const attributes = entity.attributes || {}
  const a: Record<string, any> = {}
  for (const name of ATTRS) {
    const value = attributes[name]
    if (value !== undefined && value !== null) a[name] = Array.isArray(value) ? value.slice(0, 8) : value
  }
  return { state: String(entity.state ?? ''), changed: Date.parse(entity.last_changed || '') || 0, a }
}

// What the app keeps between renders (frameos.remember): one entry per
// entity, with when it was fetched, how long a tap's guess holds, the
// card's own error and a draft while a slider is dragged.
type Kept = { at: number; hold?: number; s?: Slim; error?: string; sent?: number }
const loadKept = (): Record<string, Kept> => (frameos.recall('states') as any) || {}
const saveKept = (kept: Record<string, Kept>) => frameos.remember('states', kept as any)

const ENTITY_ID = /^[a-z0-9_]+\.[a-z0-9_]+$/

// Each card reads its entity's state, its slider's draft and the lock being
// asked about through signals: a tap runs only the card it changed, not get().
const states: Record<string, any> = {}
const stateOf = (id: string) => states[id] || (states[id] = signal(undefined))
const drafts: Record<string, any> = {}
const draftOf = (id: string) => drafts[id] || (drafts[id] = signal(null))
const asking = signal('')
const setAsking = (id: string) => {
  frameos.remember('asking', id)
  asking.value = id
}

// Fetches the states of the cards showing that are not fresh. Stops at the
// first answer that says no request will work (no network, a bad token).
function fetchStates(server: Server, entries: Entry[]): string {
  const kept = loadKept()
  const now = Date.now()
  let problem = ''
  for (const entry of entries) {
    const id = entry.ref
    if (!ENTITY_ID.test(id)) continue
    const known = kept[id]
    if (known && (now - known.at < FRESH_MS || (known.hold && now < known.hold))) continue
    const reply = call(server, 'GET', `/api/states/${id}`)
    if (reply.status === 200 && reply.data) {
      kept[id] = { at: now, s: slim(reply.data) }
    } else if (reply.status === 404) {
      kept[id] = { at: now, error: 'Not found in Home Assistant: check the entity id' }
    } else if (reply.status && reply.status !== 401 && reply.status !== 403) {
      kept[id] = { at: now, s: known?.s, error: problemText(server, reply) }
    } else {
      problem = problemText(server, reply)
      break
    }
  }
  saveKept(kept)
  if (!problem) frameos.remember('fetchedAt', now)
  return problem
}

// Calls a service for one card. `guess` is what the card should show at once
// (its state and attributes as the call will leave them).
function callService(server: Server, id: string, service: string, data: Record<string, any>, guess?: Partial<Slim>) {
  const [domain, name] = service.split('.')
  const kept = loadKept()
  const card = kept[id] || { at: 0 }
  if (guess && card.s) {
    card.s = { ...card.s, ...guess, a: { ...card.s.a, ...(guess.a || {}) } }
    card.hold = Date.now() + HOLD_MS
  }
  const reply = call(server, 'POST', `/api/services/${domain}/${name}`, { entity_id: id, ...data })
  if (reply.status >= 200 && reply.status < 300) {
    card.error = ''
    card.sent = Date.now()
    // The answer lists the states the call changed: this card's among them,
    // unless the device is slow, and sometimes others (a light group).
    for (const changed of Array.isArray(reply.data) ? reply.data : []) {
      if (!changed || !changed.entity_id) continue
      if (changed.entity_id === id) {
        card.s = slim(changed)
        card.at = Date.now()
        card.hold = 0
      } else if (kept[changed.entity_id]) {
        kept[changed.entity_id] = { at: Date.now(), s: slim(changed) }
      }
    }
  } else {
    card.error = problemText(server, reply)
    card.at = 0
    card.hold = 0
  }
  kept[id] = card
  saveKept(kept)
  // The cards it changed show it at once. A failed call sets no signal:
  // get() draws it, asking Home Assistant again, as it always did.
  if (card.error) return
  stateOf(id).value = card
  for (const changed of Array.isArray(reply.data) ? reply.data : [])
    if (changed && changed.entity_id && changed.entity_id !== id && kept[changed.entity_id]) stateOf(changed.entity_id).value = kept[changed.entity_id]
}

// ---------------------------------------------------------------- what each card is

const TOGGLES = ['switch', 'input_boolean', 'automation', 'siren', 'humidifier', 'remote', 'water_heater']
const TYPE_OF: Record<string, string> = {
  light: 'light', fan: 'fan', climate: 'climate', cover: 'cover', media_player: 'media', lock: 'lock',
  scene: 'action', script: 'action', button: 'action', input_button: 'action',
  sensor: 'sensor', binary_sensor: 'sensor', vacuum: 'vacuum', alarm_control_panel: 'alarm', weather: 'weather',
  input_number: 'number', number: 'number',
}
const TYPES = ['toggle', 'light', 'fan', 'climate', 'cover', 'media', 'lock', 'action', 'sensor', 'vacuum', 'alarm', 'weather', 'number']

function typeOf(domain: string, asked?: string) {
  const wanted = String(asked || '').toLowerCase()
  if (wanted === 'button' || wanted === 'scene' || wanted === 'script') return 'action'
  if (TYPES.includes(wanted)) return wanted
  if (TOGGLES.includes(domain)) return 'toggle'
  return TYPE_OF[domain] || 'sensor'
}

const WEATHER: Record<string, string> = {
  'clear-night': 'moon', cloudy: 'cloud', exceptional: 'alert', fog: 'fog', hail: 'snow', lightning: 'storm',
  'lightning-rainy': 'storm', partlycloudy: 'partly', pouring: 'rain', rainy: 'rain', snowy: 'snow',
  'snowy-rainy': 'snow', sunny: 'sun', windy: 'wind', 'windy-variant': 'wind',
}
const SENSOR_ICONS: Record<string, string> = {
  temperature: 'thermostat', humidity: 'droplet', moisture: 'droplet', power: 'bolt', energy: 'bolt', current: 'bolt',
  voltage: 'bolt', battery: 'battery', illuminance: 'sun', door: 'door', garage_door: 'door', opening: 'door',
  window: 'window', motion: 'motion', occupancy: 'motion', presence: 'motion', smoke: 'alert', gas: 'alert',
  carbon_monoxide: 'alert', problem: 'alert', safety: 'alert', plug: 'plug', outlet: 'plug', tv: 'tv', speaker: 'speaker',
  receiver: 'speaker', garage: 'door', gate: 'door', blind: 'blinds', shade: 'blinds', shutter: 'blinds', curtain: 'blinds',
  sound: 'volume', connectivity: 'toggle', precipitation: 'rain', wind_speed: 'wind',
}
const DOMAIN_ICONS: Record<string, string> = {
  light: 'bulb', switch: 'power', fan: 'fan', input_boolean: 'toggle', automation: 'robot', climate: 'thermostat',
  cover: 'blinds', media_player: 'tv', lock: 'lock', scene: 'sparkles', script: 'script', button: 'button',
  input_button: 'button', sensor: 'gauge', binary_sensor: 'toggle', vacuum: 'vacuum', alarm_control_panel: 'shield',
  weather: 'partly', person: 'person', device_tracker: 'person', sun: 'sun', input_number: 'slider', number: 'slider',
  siren: 'bell', humidifier: 'droplet', water_heater: 'heater', remote: 'tv', zone: 'home',
}

function iconFor(entry: Entry, domain: string, s?: Slim) {
  const asked = iconName(entry.opts.icon)
  if (asked) return asked
  const own = iconName(s?.a.icon)
  if (own) return own
  if (domain === 'weather' && s) return WEATHER[s.state] || 'partly'
  if (domain === 'lock' && s?.state === 'unlocked') return 'unlock'
  if (domain === 'sun' && s?.state === 'below_horizon') return 'moon'
  return SENSOR_ICONS[s?.a.device_class] || DOMAIN_ICONS[domain] || 'gauge'
}

// How a binary sensor's on and off read, by its device class.
const BINARY: Record<string, [string, string]> = {
  door: ['Open', 'Closed'], garage_door: ['Open', 'Closed'], opening: ['Open', 'Closed'], window: ['Open', 'Closed'],
  motion: ['Motion', 'Clear'], occupancy: ['Occupied', 'Clear'], presence: ['Home', 'Away'], moisture: ['Wet', 'Dry'],
  smoke: ['Smoke!', 'Clear'], gas: ['Gas!', 'Clear'], carbon_monoxide: ['CO!', 'Clear'], problem: ['Problem', 'OK'],
  safety: ['Unsafe', 'Safe'], battery: ['Low', 'Normal'], lock: ['Unlocked', 'Locked'], connectivity: ['Connected', 'Disconnected'],
  plug: ['Plugged in', 'Unplugged'], power: ['Power', 'No power'], running: ['Running', 'Not running'], tamper: ['Tampered', 'Clear'],
  vibration: ['Vibration', 'Still'], sound: ['Sound', 'Quiet'], light: ['Light', 'Dark'], heat: ['Hot', 'Normal'], cold: ['Cold', 'Normal'],
}
const ALARMING = ['smoke', 'gas', 'carbon_monoxide', 'problem', 'safety', 'moisture', 'tamper', 'heat', 'cold']

// ---------------------------------------------------------------- drawing the cards

type Ctx = {
  t: Theme; z: Sizes; fast: boolean; compact: boolean; showUpdated: boolean; confirmLocks: boolean
  // A narrow card leaves out what the name needs the room for (a switch: the card's color says on or off).
  narrow: boolean
  server: Server
}

// A slider's value while a finger drags it, else the state's.
const draftOr = (id: string, key: string, value: number) => {
  const draft = draftOf(id).value
  return draft && draft.key === key ? draft.v : value
}
const setDraft = (id: string, key: string, v: number) => {
  const was = frameos.recall('draft') as any
  if (was && was.id !== id) draftOf(was.id).value = null
  frameos.remember('draft', { id, key, v })
  draftOf(id).value = { id, key, v }
}
const dropDraft = (id: string) => {
  frameos.remember('draft', null)
  draftOf(id).value = null
}

const EntityCard = memo(({ entry, ctx }: { entry: Entry; ctx: Ctx }) => {
  const { t, z } = ctx
  const now = Date.now()
  const id = entry.ref
  const kept: Kept | undefined = stateOf(id).value
  // A guess from a tap holds a few seconds: on a fast screen, look again then.
  if (ctx.fast && (kept?.hold || 0) > now) frameos.setNextSleep(HOLD_MS / 1000 + 0.5)
  const domain = id.split('.')[0]
  const s = kept?.s
  const type = typeOf(domain, entry.opts.type)
  const name = entry.name || s?.a.friendly_name || words(id.split('.')[1] || id)
  const icon = iconFor(entry, domain, s)
  const base = { t, z, icon, name, compact: ctx.compact, error: kept?.error }
  if (!ENTITY_ID.test(id)) return <Card {...base} look="gone" error={`Not an entity id: "${id}" (like light.kitchen)`} />
  if (!s) return <Card {...base} look="gone" sub={kept?.error ? '' : 'No state yet'} />
  if (s.state === 'unavailable' || s.state === 'unknown' && type !== 'action' && type !== 'sensor')
    return <Card {...base} look="gone" sub={capitalize(s.state)} />

  const run = (service: string, data: Record<string, any> = {}, guess?: Partial<Slim>) =>
    callService(ctx.server, id, service, data, guess)
  const since = ctx.showUpdated && s.changed ? ` · ${ago(s.changed, now)}` : ''
  const a = s.a
  const isOn = s.state === 'on'

  if (type === 'toggle' || type === 'light' || type === 'fan') {
    // On and off, and for a light its brightness (and white tone), for a fan its speed.
    const service = TOGGLES.includes(domain) || domain === 'light' || domain === 'fan' ? domain : 'homeassistant'
    const toggle = () => run(`${service}.${isOn ? 'turn_off' : 'turn_on'}`, {}, { state: isOn ? 'off' : 'on' })
    const modes: string[] = a.supported_color_modes || []
    const dims = type === 'light' && modes.length > 0 && !(modes.length === 1 && modes[0] === 'onoff')
    const warmth = type === 'light' && isOn && modes.includes('color_temp') && a.min_color_temp_kelvin && a.max_color_temp_kelvin
    const speed = type === 'fan' && a.percentage !== undefined
    const level = dims ? draftOr(id, 'brightness', isOn ? (a.brightness ?? 255) / 255 : 0) : speed ? draftOr(id, 'percentage', (a.percentage ?? 0) / 100) : 0
    let sub = isOn ? 'On' : 'Off'
    if (isOn && dims) sub = `On · ${Math.round(level * 100)}%`
    if (isOn && speed) sub = `On · speed ${Math.round(level * 100)}%`
    if (domain === 'automation' && a.last_triggered) sub += ` · ran ${ago(Date.parse(a.last_triggered), now)}`
    else if (!(isOn && (dims || speed))) sub += since
    const kelvinLow = a.min_color_temp_kelvin
    const kelvinHigh = a.max_color_temp_kelvin
    const kelvin = warmth ? draftOr(id, 'kelvin', ((a.color_temp_kelvin ?? kelvinLow) - kelvinLow) / Math.max(1, kelvinHigh - kelvinLow)) : 0
    return (
      <Card {...base} look={isOn ? 'on' : 'off'} sub={sub} right={ctx.narrow ? null : <Switch t={t} z={z} on={isOn} />} onTap={toggle}>
        {dims ? (
          <Slider t={t} z={z} on={isOn} value={level} icon="sun" fast={ctx.fast} label={`Brightness ${Math.round(level * 100)}%`}
            onDraft={(v) => setDraft(id, 'brightness', v)}
            onSet={(v) => {
              dropDraft(id)
              const pct = Math.max(1, Math.round(v * 100))
              run('light.turn_on', { brightness_pct: pct }, { state: 'on', a: { brightness: Math.round((pct * 255) / 100) } })
            }} />
        ) : null}
        {warmth ? (
          <Slider t={t} z={z} on={isOn} value={kelvin} icon="thermostat" fast={ctx.fast}
            label={`${kelvin < 0.35 ? 'Warm' : kelvin > 0.65 ? 'Cool' : 'Neutral'} white`}
            onDraft={(v) => setDraft(id, 'kelvin', v)}
            onSet={(v) => {
              dropDraft(id)
              const k = Math.round(kelvinLow + v * (kelvinHigh - kelvinLow))
              run('light.turn_on', { color_temp_kelvin: k }, { a: { color_temp_kelvin: k } })
            }} />
        ) : null}
        {speed ? (
          <Slider t={t} z={z} on={isOn} value={level} icon="fan" fast={ctx.fast} label={`Speed ${Math.round(level * 100)}%`}
            onDraft={(v) => setDraft(id, 'percentage', v)}
            onSet={(v) => {
              dropDraft(id)
              const pct = Math.round(v * 100)
              run('fan.set_percentage', { percentage: pct }, { state: pct > 0 ? 'on' : 'off', a: { percentage: pct } })
            }} />
        ) : null}
      </Card>
    )
  }

  if (type === 'climate') {
    // The room's temperature, the target with - and +, and the modes.
    const target = typeof a.temperature === 'number' ? a.temperature : null
    const step = a.target_temp_step || 0.5
    const low = a.min_temp ?? 5
    const high = a.max_temp ?? 35
    const working = ['heating', 'cooling', 'drying', 'fan'].includes(a.hvac_action)
    const nudge = (by: number) => {
      if (target === null) return
      const next = Math.round(clamp(target + by, low, high) / step) * step
      run('climate.set_temperature', { temperature: next }, { a: { temperature: next } })
    }
    const current = typeof a.current_temperature === 'number' ? niceNumber(a.current_temperature) : '-'
    let sub = s.state === 'off' ? 'Off' : a.hvac_action ? capitalize(a.hvac_action) : words(s.state)
    if (ctx.narrow) sub = `${current}° · ${s.state === 'off' ? 'off' : a.hvac_action || words(s.state)}`
    if (target !== null && s.state !== 'off') sub += ` to ${niceNumber(target)}°`
    else if (a.target_temp_low !== undefined && a.target_temp_high !== undefined && s.state !== 'off')
      sub += ` ${niceNumber(a.target_temp_low)}-${niceNumber(a.target_temp_high)}°`
    const modes: string[] = (a.hvac_modes || []).slice(0, 4)
    if (!modes.includes(s.state) && a.hvac_modes?.includes(s.state)) modes[3] = s.state
    return (
      <Card {...base} look={working ? 'on' : 'normal'} icon={a.hvac_action === 'cooling' ? 'snowflake' : a.hvac_action === 'heating' ? 'flame' : icon}
        sub={sub} right={ctx.narrow ? null : <Value z={z} text={current} unit="°" />}>
        {target !== null ? (
          <div className={`flex items-center gap-[${z.s(8)}px]`}>
            <Button t={t} z={z} on={working} icon="minus" onClick={() => nudge(-step)} />
            <div className="flex-1 flex flex-col items-center">
              <span className={`text-[${z.s(24)}px] font-bold leading-none`}>{`${niceNumber(target)}°`}</span>
              <span className={`text-[${z.s(12)}px] ${working ? t.subOn : t.muted}`}>target</span>
            </div>
            <Button t={t} z={z} on={working} icon="plus" onClick={() => nudge(step)} />
          </div>
        ) : null}
        {modes.length > 1 ? (
          <div className={`flex gap-[${z.s(6)}px]`}>
            {modes.map((mode) => (
              <Button t={t} z={z} on={working} wide picked={mode === s.state} label={words(mode === 'heat_cool' ? 'auto' : mode)}
                onClick={() => run('climate.set_hvac_mode', { hvac_mode: mode }, { state: mode, a: { hvac_action: mode === 'off' ? 'off' : 'idle' } })} />
            ))}
          </div>
        ) : null}
      </Card>
    )
  }

  if (type === 'cover') {
    // Open, stop and close, and the position where the cover can be set to one.
    const features = a.supported_features ?? 15
    const position = typeof a.current_position === 'number' ? draftOr(id, 'position', a.current_position / 100) : null
    const open = s.state === 'open' || s.state === 'opening'
    const sub = `${words(s.state)}${position !== null && s.state !== 'closed' ? ` · ${Math.round(position * 100)}%` : ''}${since}`
    return (
      <Card {...base} look={open ? 'on' : 'normal'} sub={sub}>
        <div className={`flex gap-[${z.s(8)}px]`}>
          {features & 1 ? <Button t={t} z={z} on={open} wide icon="up" onClick={() => run('cover.open_cover', {}, { state: 'opening' })} /> : null}
          {features & 8 ? <Button t={t} z={z} on={open} wide icon="stop" onClick={() => run('cover.stop_cover')} /> : null}
          {features & 2 ? <Button t={t} z={z} on={open} wide icon="down" onClick={() => run('cover.close_cover', {}, { state: 'closing' })} /> : null}
        </div>
        {features & 4 && position !== null ? (
          <Slider t={t} z={z} on={open} value={position} icon="blinds" fast={ctx.fast} label={`Open ${Math.round(position * 100)}%`}
            onDraft={(v) => setDraft(id, 'position', v)}
            onSet={(v) => {
              dropDraft(id)
              const pct = Math.round(v * 100)
              run('cover.set_cover_position', { position: pct }, { a: { current_position: pct }, state: pct > 0 ? 'open' : 'closed' })
            }} />
        ) : null}
      </Card>
    )
  }

  if (type === 'media') {
    // What is playing, play/pause, skip, and the volume.
    const playing = s.state === 'playing'
    const off = s.state === 'off' || s.state === 'standby'
    const song = [a.media_title, a.media_artist].filter(Boolean).join(' · ')
    const volume = typeof a.volume_level === 'number' ? draftOr(id, 'volume', a.volume_level) : null
    if (off)
      return (
        <Card {...base} look="normal" sub={capitalize(s.state)}
          right={<Button t={t} z={z} on={false} icon="power" onClick={() => run('media_player.turn_on', {}, { state: 'on' })} />} />
      )
    return (
      <Card {...base} look={playing ? 'on' : 'normal'} sub={song || (a.app_name ? `${words(s.state)} · ${a.app_name}` : words(s.state))}
        onTap={ctx.compact ? () => run('media_player.media_play_pause', {}, { state: playing ? 'paused' : 'playing' }) : undefined}>
        <div className={`flex gap-[${z.s(8)}px]`}>
          <Button t={t} z={z} on={playing} wide icon="prev" onClick={() => run('media_player.media_previous_track')} />
          <Button t={t} z={z} on={playing} wide icon={playing ? 'pause' : 'play'}
            onClick={() => run('media_player.media_play_pause', {}, { state: playing ? 'paused' : 'playing' })} />
          <Button t={t} z={z} on={playing} wide icon="next" onClick={() => run('media_player.media_next_track')} />
        </div>
        {volume !== null ? (
          <Slider t={t} z={z} on={playing} value={volume} icon="volume" fast={ctx.fast} label={`Volume ${Math.round(volume * 100)}%`}
            onDraft={(v) => setDraft(id, 'volume', v)}
            onSet={(v) => {
              dropDraft(id)
              const level = Math.round(v * 100) / 100
              run('media_player.volume_set', { volume_level: level }, { a: { volume_level: level } })
            }} />
        ) : null}
      </Card>
    )
  }

  if (type === 'lock') {
    // Locks ask first (unless the scene says not to).
    const locked = s.state === 'locked'
    const jammed = s.state === 'jammed'
    const action = locked ? 'Unlock' : 'Lock'
    const go = () => {
      setAsking('')
      run(locked ? 'lock.unlock' : 'lock.lock', {}, { state: locked ? 'unlocking' : 'locking' })
    }
    if (asking.value === id)
      return <Confirm t={t} z={z} icon={locked ? 'unlock' : 'lock'} question={`${action} ${name}?`} yes={action}
        onYes={go} onNo={() => setAsking('')} />
    const ask = () => (ctx.confirmLocks ? setAsking(id) : go())
    return (
      <Card {...base} look={jammed ? 'alert' : locked ? 'normal' : 'on'} sub={`${words(s.state)}${since}`} onTap={ctx.compact ? ask : undefined}
        right={ctx.compact ? null : <Button t={t} z={z} on={!locked} label={ctx.narrow ? undefined : action} icon={ctx.narrow ? (locked ? 'unlock' : 'lock') : undefined}
          onClick={ask} />} />
    )
  }

  if (type === 'action') {
    // A scene, script or button: a tap anywhere on it runs it. A scene's and
    // a button's state is when it last ran.
    const service = domain === 'scene' ? 'scene.turn_on' : domain === 'script' ? 'script.turn_on'
      : domain === 'button' || domain === 'input_button' ? `${domain}.press` : domain === 'automation' ? 'automation.trigger' : 'homeassistant.turn_on'
    const last = Date.parse(s.state)
    const running = domain === 'script' && s.state === 'on'
    const sent = kept?.sent && now - kept.sent < 10 * 60000 ? kept.sent : 0
    const sub = running ? 'Running' : sent ? `Done ${ago(sent, now)}` : last ? `Last ${ago(last, now)}` : domain === 'script' && a.last_triggered ? `Last ${ago(Date.parse(a.last_triggered), now)}` : 'Tap to run'
    return (
      <Card {...base} look={running ? 'on' : 'normal'} sub={sub} onTap={() => run(service)}
        right={ctx.compact ? null : <Button t={t} z={z} on={running} icon="play" onClick={() => run(service)} />} />
    )
  }

  if (type === 'vacuum') {
    const cleaning = s.state === 'cleaning'
    const battery = typeof a.battery_level === 'number' ? ` · battery ${a.battery_level}%` : ''
    return (
      <Card {...base} look={cleaning ? 'on' : s.state === 'error' ? 'alert' : 'normal'} sub={`${words(a.status || s.state)}${battery}`}>
        <div className={`flex gap-[${z.s(8)}px]`}>
          <Button t={t} z={z} on={cleaning} wide picked={cleaning} icon={cleaning ? 'pause' : 'play'} label={cleaning ? 'Pause' : 'Start'}
            onClick={() => run(cleaning ? 'vacuum.pause' : 'vacuum.start', {}, { state: cleaning ? 'paused' : 'cleaning' })} />
          <Button t={t} z={z} on={cleaning} wide icon="dock" label="Dock"
            onClick={() => run('vacuum.return_to_base', {}, { state: 'returning' })} />
        </div>
      </Card>
    )
  }

  if (type === 'alarm') {
    // Read only: arming from a frame on the wall would need the code.
    const armed = s.state.startsWith('armed')
    const alarm = s.state === 'triggered'
    return <Card {...base} look={alarm ? 'alert' : armed ? 'on' : 'normal'} sub={`${words(s.state)}${since}`} />
  }

  if (type === 'weather') {
    const unit = a.temperature_unit || '°'
    const humidity = typeof a.humidity === 'number' ? ` · ${Math.round(a.humidity)}% humidity` : ''
    return (
      <Card {...base} look="normal" sub={`${words(s.state === 'partlycloudy' ? 'partly cloudy' : s.state.replace(/-/g, ' '))}${humidity}`}
        right={typeof a.temperature === 'number' ? <Value z={z} text={niceNumber(a.temperature)} unit={unit} /> : null} />
    )
  }

  if (type === 'number') {
    const low = Number(a.min ?? 0)
    const high = Number(a.max ?? 100)
    const step = Number(a.step ?? 1)
    const value = Number(s.state)
    const fraction = draftOr(id, 'value', (value - low) / Math.max(1e-9, high - low))
    const shown = Math.round((low + fraction * (high - low)) / step) * step
    return (
      <Card {...base} look="normal" sub={since.slice(3)} right={<Value z={z} text={niceNumber(value)} unit={a.unit_of_measurement} />}>
        <Slider t={t} z={z} on={false} value={fraction} icon="slider" fast={ctx.fast} label={`Set ${niceNumber(shown)}${a.unit_of_measurement || ''}`}
          onDraft={(v) => setDraft(id, 'value', v)}
          onSet={(v) => {
            dropDraft(id)
            const next = Math.round((low + v * (high - low)) / step) * step
            run(`${domain}.set_value`, { value: next }, { state: String(next) })
          }} />
      </Card>
    )
  }

  // A sensor, a binary sensor, or anything else: its state.
  if (domain === 'binary_sensor') {
    const words2 = BINARY[a.device_class] || ['On', 'Off']
    const look: Look = isOn ? (ALARMING.includes(a.device_class) ? 'alert' : 'on') : 'normal'
    return <Card {...base} look={look} sub={ctx.showUpdated && s.changed ? `Since ${ago(s.changed, now)}` : ''}
      right={<span className={`shrink-0 text-[${z.s(18)}px] font-bold`}>{isOn ? words2[0] : words2[1]}</span>} />
  }
  const number = Number(s.state)
  const numeric = s.state !== '' && Number.isFinite(number)
  const unit = a.unit_of_measurement || ''
  const text = numeric ? niceNumber(number) : words(s.state)
  const sub = ctx.showUpdated && s.changed ? `Changed ${ago(s.changed, now)}` : a.device_class ? words(a.device_class) : ''
  return (
    <Card {...base} look="normal" sub={sub}
      right={numeric || text.length <= 10 ? <Value z={z} text={text} unit={unit} /> : <span className={`shrink-0 max-w-[50%] text-[${z.s(16)}px] font-bold truncate`}>{text}</span>} />
  )
})

// ---------------------------------------------------------------- the scene

const pageOf = (count: number) => {
  const page = Number(frameos.recall('page') || 0)
  return count ? ((page % count) + count) % count : 0
}

export function onEvent(app, context) {
  // back / forward (a swipe in from a screen edge, or a key bound to them)
  // and the arrow keys turn the pages.
  const p = context.payload || {}
  let by = 0
  if (context.event === 'forward') by = 1
  else if (context.event === 'back') by = -1
  else if (context.event === 'keyDown' && !p.ctrl && !p.alt && !p.meta) {
    if (p.key === 'ArrowRight' || p.key === 'PageDown') by = 1
    else if (p.key === 'ArrowLeft' || p.key === 'PageUp') by = -1
  }
  if (!by) return false
  frameos.remember('page', Number(frameos.recall('page') || 0) + by)
  frameos.remember('asking', '')
  return true
}

// On a round panel (only the circle inside the square shows) the cards are
// laid out in the square inside that circle, 12 px in from the rim
// (roundRoom), and a setup screen uses the circle (SetupScreen): both at
// their sizes for 480 px, never smaller, so text stays readable there.
export function get(app, context) {
  if (context?.round !== true) return getIn(app, context, sizesOf(app, context))
  const W = context.imageWidth, H = context.imageHeight
  const side = Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2)
  const k = 1 // the frame's render scale makes it larger on a big panel
  return getIn(app, context, { W: side, H: side, k, s: (px: number) => Math.round(px * k), portrait: false, round: { W, H } })
}

function getIn(app, context, z: Sizes) {
  const t = themeOf(app)
  const server = serverOf()
  if (!server)
    return (
      <SetupScreen t={t} z={z} icon="home" title="Connect Home Assistant"
        intro="This remote needs your Home Assistant's address and an access token."
        steps={[
          { head: 'Make an access token', text: 'In Home Assistant: your profile, Security tab, Long-lived access tokens, Create token.' },
          {
            head: 'Add it to FrameOS',
            text: "In FrameOS: Settings, Home Assistant. Fill in the URL and the access token. Every frame of the account uses them.",
            code: 'http://homeassistant.local:8123',
          },
          { head: 'Pick the cards', text: "In this scene's settings, list entities under Cards, one per line. A # line starts a page.", code: 'light.kitchen | Kitchen' },
        ]}
        note="On a frame managed by FrameOS Cloud, turn on Local network access in the frame's settings to reach a Home Assistant at home." />
    )

  const title = String(app.state.title ?? '').trim() || 'Home'
  const pages: Page[] = parseCards(app.state.cards, title)
  if (!pages.length)
    return (
      <SetupScreen t={t} z={z} icon="toggle" title="Add your cards"
        intro={`Connected to ${originOf(server.url)}. Now say what to show.`}
        steps={[
          { head: 'One entity per line', text: "In this scene's settings, under Cards. Find the ids in Home Assistant: Settings, Devices & services, Entities.", code: 'light.kitchen' },
          { head: 'Your own names and icons', text: 'After a |, a name; icon= and type= change how a card looks.', code: 'switch.fan | Fan | icon=fan' },
          { head: 'Pages', text: 'A line starting with # starts a page, a tab at the top. Swipe in from an edge to turn pages.', code: '# Downstairs' },
        ]} />
    )

  const page = pageOf(pages.length)
  const entries = pages[page].entries
  const problem = fetchStates(server, entries)
  const kept = loadKept()
  const now = Date.now()
  const draft = (frameos.recall('draft') as any) || null
  asking.value = String(frameos.recall('asking') || '')
  for (const entry of entries) {
    stateOf(entry.ref).value = kept[entry.ref]
    draftOf(entry.ref).value = draft && draft.id === entry.ref ? draft : null
  }
  const compact = app.state.compact === true || app.state.compact === 'true'
  const showUpdated = app.state.showUpdated !== false && app.state.showUpdated !== 'false'
  const ctx: Ctx = {
    t, z, server, compact, showUpdated,
    fast: app.frame.fast !== false,
    confirmLocks: app.state.confirmLocks !== false && app.state.confirmLocks !== 'false',
    narrow: false,
  }
  // A guess from a tap holds a few seconds: on a fast screen, look again
  // then; e-paper keeps what Home Assistant answered to the tap.
  if (ctx.fast && entries.some((entry) => (kept[entry.ref]?.hold || 0) > now)) frameos.setNextSleep(HOLD_MS / 1000 + 0.5)

  const fetchedAt = Number(frameos.recall('fetchedAt') || 0)
  const columns = columnsFor(String(app.state.columns || 'auto'), z, compact)
  const tabsBelow = app.state.tabs === 'bottom'
  const pick = (index: number) => {
    frameos.remember('page', index)
    frameos.remember('asking', '')
  }
  const refresh = () => {
    const all = loadKept()
    for (const id in all) all[id].at = 0
    saveKept(all)
  }
  const tabs = <Tabs t={t} z={z} pages={pages} page={page} onPick={pick} />
  const gap = z.s(compact ? 8 : 10)
  ctx.narrow = (z.W - 2 * z.s(14) - gap * (columns - 1)) / columns < z.s(250)
  return roundRoom(t, z,
    <div className={`flex flex-col w-full h-full gap-[${z.s(10)}px] p-[${z.s(14)}px] ${t.page}`}>
      <Header t={t} z={z} title={title}
        updated={showUpdated && fetchedAt ? `Updated ${clockTime(fetchedAt)}` : ''} onRefresh={refresh} />
      {tabsBelow ? null : tabs}
      {problem ? (
        <div className={`flex items-center gap-[${z.s(10)}px] rounded-[${z.s(14)}px] px-[${z.s(12)}px] py-[${z.s(8)}px] ${t.banner}`}>
          <Icon name="alert" size={z.s(22)} />
          <span className={`flex-1 text-[${z.s(14)}px] line-clamp-2`}>{problem}</span>
        </div>
      ) : null}
      <div className="flex-1 min-h-0 overflow-y-auto">
        <div className={`grid grid-cols-${columns} gap-[${gap}px]`}>
          {entries.map((entry) => <EntityCard entry={entry} ctx={ctx} />)}
        </div>
      </div>
      {tabsBelow ? tabs : null}
    </div>,
  )
}

sources.ui.tsx:
// The parts of the remote that do not care where the devices live: the card
// list's syntax, the two themes, sizes worked out from the canvas, icons,
// cards, sliders, buttons and the page tabs. app.tsx speaks to the home
// server and decides what each card shows; this file only draws.

// ---------------------------------------------------------------- the list

// The Cards setting, one card per line:
//   light.kitchen                      a card, named as the server names it
//   switch.fan | Fan                   ... with a name of its own
//   sensor.outside | icon=sun          ... with another icon
//   cover.blinds | Blinds | type=cover ... drawn as another kind of card
//   # Downstairs                       a new page (a tab) for the cards below
//   // a note                          ignored
// Cards before the first "#" line go on a page named after the title.
export type Entry = { ref: string; name: string; opts: Record<string, string> }
export type Page = { title: string; entries: Entry[] }

export function parseCards(text: string, firstTitle: string): Page[] {
  const pages: Page[] = []
  let page: Page | null = null
  for (const raw of String(text || '').split('\n')) {
    const line = raw.trim()
    if (!line || line.startsWith('//')) continue
    if (line.startsWith('#')) {
      page = { title: line.replace(/^#+/, '').trim() || `Page ${pages.length + 1}`, entries: [] }
      pages.push(page)
      continue
    }
    const parts = line.split('|').map((part) => part.trim())
    const entry: Entry = { ref: parts[0], name: '', opts: {} }
    for (const part of parts.slice(1)) {
      const option = /^([a-zA-Z]+)\s*=\s*(.*)$/.exec(part)
      if (option) entry.opts[option[1].toLowerCase()] = option[2].trim()
      else if (part && !entry.name) entry.name = part
    }
    if (!entry.ref) continue
    if (!page) {
      page = { title: firstTitle, entries: [] }
      pages.push(page)
    }
    page.entries.push(entry)
  }
  return pages.filter((each) => each.entries.length > 0)
}

// ---------------------------------------------------------------- looks

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
export const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// Deep slate with one accent (amber) for what is on, or pure black on white
// with borders and black fills for what is on: no greys to dither.
const THEMES = {
  color: {
    page: 'bg-[#0f172a] text-slate-100',
    muted: 'text-slate-400',
    card: 'bg-[#1e293b] text-slate-100',
    cardOn: 'bg-amber-300 text-amber-950',
    cardAlert: 'bg-rose-300 text-rose-950',
    cardOff: 'bg-[#1e293b] text-slate-500',
    bubble: 'bg-[#334155] text-slate-200',
    bubbleOn: 'bg-amber-950 text-amber-300',
    bubbleAlert: 'bg-rose-950 text-rose-200',
    subOn: 'text-amber-900',
    // Sliders: the label sits on the bar, light on both its parts.
    overlay: true,
    track: 'bg-[#334155] text-slate-50',
    trackOn: 'bg-amber-950 text-amber-50',
    fill: 'bg-[#64748b]',
    fillOn: 'bg-amber-700',
    button: 'bg-[#334155] text-slate-100 active:bg-[#475569]',
    buttonOn: 'bg-amber-950 text-amber-200 active:bg-amber-900',
    picked: 'bg-amber-300 text-amber-950',
    pickedOn: 'bg-amber-50 text-amber-950',
    primary: 'bg-amber-300 text-amber-950 active:bg-amber-400',
    switchOn: 'bg-amber-950 justify-end',
    switchOff: 'bg-[#475569] justify-start',
    knob: 'bg-amber-300',
    knobOff: 'bg-slate-200',
    tab: 'text-slate-300 bg-[#1e293b]',
    tabOn: 'bg-amber-300 text-amber-950',
    error: 'text-rose-300',
    errorOn: 'text-rose-800',
    banner: 'bg-rose-950 text-rose-100',
    code: 'bg-[#1e293b] text-amber-200',
    step: 'bg-amber-300 text-amber-950',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    card: 'bg-white text-black border-2 border-black',
    cardOn: 'bg-black text-white border-2 border-black',
    cardAlert: 'bg-black text-white border-2 border-black',
    cardOff: 'bg-white text-black border-2 border-black',
    bubble: 'bg-white text-black border-2 border-black',
    bubbleOn: 'bg-white text-black',
    bubbleAlert: 'bg-white text-black',
    subOn: 'text-white',
    // Sliders: the label above a bordered bar, so no text sits on black and white at once.
    overlay: false,
    track: 'bg-white border-2 border-black',
    trackOn: 'bg-black border-2 border-white',
    fill: 'bg-black',
    fillOn: 'bg-white',
    button: 'bg-white text-black border-2 border-black',
    buttonOn: 'bg-black text-white border-2 border-white',
    picked: 'bg-black text-white border-2 border-black',
    pickedOn: 'bg-white text-black border-2 border-white',
    primary: 'bg-black text-white border-2 border-black',
    switchOn: 'bg-white border-2 border-white justify-end',
    switchOff: 'bg-white border-2 border-black justify-start',
    knob: 'bg-black',
    knobOff: 'bg-black',
    tab: 'bg-white text-black border-2 border-black',
    tabOn: 'bg-black text-white border-2 border-black',
    error: 'text-black',
    errorOn: 'text-white',
    banner: 'bg-black text-white',
    code: 'bg-white text-black border-2 border-black',
    step: 'bg-black text-white',
  },
}
// Colour e-paper (a Spectra's six inks) has no greys: the same look on solid
// black, white text and borders where the slate ones would dither to noise.
const INK = {
  ...THEMES.color,
  page: 'bg-black text-white',
  muted: 'text-white',
  card: 'bg-black text-white border-2 border-white',
  cardOff: 'bg-black text-white border-2 border-white',
  bubble: 'bg-white text-black',
  tab: 'bg-black text-white border-2 border-white',
  code: 'bg-black text-[#ffff00] border-2 border-[#ffff00]',
  step: 'bg-[#ffff00] text-black',
}
export type Theme = typeof THEMES.color
export const themeOf = (app): Theme =>
  highContrast(app) ? THEMES.high : app.frame.paper === true ? INK : THEMES.color

// Every length comes from the canvas: 1 at 800x480 or 480x480, less on a
// smaller one; a big panel makes it larger by the frame's render scale
// (automatic: 2 on a 10" e-paper), not here. s(16) is what 16 px is on this frame.
export function sizesOf(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const k = Math.max(0.85, Math.min(1, Math.min(W, H) / 480))
  const s = (px: number) => Math.round(px * k)
  return { W, H, k, s, portrait: H > W }
}
// `round`: the panel's whole canvas on a round panel (only the circle inside
// it shows), with W and H the square inside that circle.
export type Sizes = ReturnType<typeof sizesOf> & { round?: { W: number; H: number } }

// On a round panel: the UI in the square inside the circle, 12 px in from
// the rim; elsewhere the UI as it is.
export function roundRoom(t: Theme, z: Sizes, ui: any) {
  if (!z.round) return ui
  const { W, H } = z.round
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${(W - z.W) >> 1}px] top-[${(H - z.H) >> 1}px] w-[${z.W}px] h-[${z.H}px]`}>{ui}</div>
    </div>
  )
}

// How many columns: the setting, or as many cards as fit side by side.
export function columnsFor(setting: string, z: Sizes, compact: boolean) {
  const asked = parseInt(setting, 10)
  if (asked >= 1 && asked <= 6) return asked
  const inner = z.W - z.s(32)
  const fits = Math.floor(inner / z.s(compact ? 160 : 215))
  return Math.max(1, Math.min(4, fits))
}

// ---------------------------------------------------------------- icons

// Line icons in a 24x24 box, drawn in the text color. Each is one path (a few
// with an extra circle); names are what "| icon=..." takes.
const PATHS: Record<string, string> = {
  bulb: 'M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z',
  power: 'M12 2v10M18.4 6.6a9 9 0 1 1-12.8 0',
  plug: 'M9 2v6M15 2v6M6 8h12v4a6 6 0 0 1-12 0zM12 18v4',
  fan: 'M10.8 16.4a6.1 6.1 0 0 1-8.6-7l5.4 1.4a6.1 6.1 0 0 1 7-8.6l-1.4 5.4a6.1 6.1 0 0 1 8.6 7l-5.4-1.4a6.1 6.1 0 0 1-7 8.6z',
  thermostat: 'M14 14.8V4.5a2.5 2.5 0 0 0-5 0v10.3a4.5 4.5 0 1 0 5 0zM11.5 17.5v-6',
  flame: 'M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.4-.5-2-1-3-1.1-2.1-.2-4.1 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.2.4-2.3 1-3a2.5 2.5 0 0 0 2.5 2.5z',
  snowflake: 'M12 2v20M3.3 7l17.4 10M3.3 17L20.7 7M9 4l3 2 3-2M9 20l3-2 3 2',
  blinds: 'M4 3h16M5 3v15M19 3v15M5 7h14M5 11h14M5 15h14M4 18h16M12 18v3',
  tv: 'M3 7h18v13H3zM17 2l-5 5-5-5',
  speaker: 'M6 2h12v20H6zM12 6h.01M12 11a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7z',
  music: 'M9 18V5l12-2v13M9 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0zM21 16a3 3 0 1 1-6 0 3 3 0 0 1 6 0z',
  lock: 'M5 11h14v10H5zM8 11V7a4 4 0 0 1 8 0v4M12 15v2',
  unlock: 'M5 11h14v10H5zM8 11V7a4 4 0 0 1 7.7-1.5M12 15v2',
  sparkles: 'M12 3l1.9 5.1L19 10l-5.1 1.9L12 17l-1.9-5.1L5 10l5.1-1.9zM19 16l.8 2.2L22 19l-2.2.8L19 22l-.8-2.2L16 19l2.2-.8z',
  script: 'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20zM10 8l6 4-6 4z',
